#!/usr/bin/env bash
# ncpgen's tests, with no vendor file at all: npunet.py's and frame.py's self-tests, then every network of
# tests/golden.txt (our own seeded networks: the corpus, a final unseen set of larger chains, the models of
# models/zoo.py, rows "zoo:<model>", the stride rewrites' networks, rows "restride:<case>", and the ADD-as-conv
# networks of ncpgen/add_sweep.py, rows "add:probe|random:<name>") generated by ncpgen
# with NPUC's own activation table (--grelu npuc) and compared by
# sha256 with the NCP Samsung's NPUC compiled for it, every zoo model written as TFLite (npunet.graph_to_tflite)
# lowering to the same network as its JSON (models/zoo.py write: "tflite: ok"), and npunet's stride rewrites giving the
# CPU reference of the original network on random inputs (tests/rewrite_ref.py: the published kws-cnn, magic-wand and
# alexnet-96 and a small network per rewrite form, against a direct reference of the original graph).
#   tests/run.sh [-j N]          exit 0 when everything passes
set -uo pipefail
R=$(cd "$(dirname "$0")/.." && pwd)
J=4; [ "${1:-}" = -j ] && J=$2
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
fail=0
python3 -I "$R/ncpgen/npunet.py" selftest | tail -n 1 | grep -q PASS && echo "npunet selftest: PASS" || { echo "npunet selftest: FAIL"; fail=1; }
python3 -I "$R/ncpgen/frame.py" selftest | tail -n 1 | grep -q PASS && echo "frame selftest: PASS" || { echo "frame selftest: FAIL"; fail=1; }
rw=$(python3 -I "$R/tests/rewrite_ref.py" --jobs "$J")
echo "$rw" | grep ' FAIL ' || true
echo "stride rewrites: $(echo "$rw" | grep -c ' ok ') of $(echo "$rw" | grep -c -e ' ok ' -e ' FAIL ') networks give the original's reference ($(echo "$rw" | tail -n 1 | sed 's/^rewrite_ref: //'))"
echo "$rw" | tail -n 1 | grep -q PASS || fail=1
one() {
  IFS='|' read -r name spec opts sha <<< "$1"
  case "$spec" in
    zoo:*) src="$T/$name/${spec#zoo:}.json"
           python3 -I "$R/models/zoo.py" write "$T/$name" --no-tflite "${spec#zoo:}" > /dev/null 2>&1 ;;
    restride:*) src="$T/$name/${spec#restride:}.json"
           python3 -I "$R/tests/rewrite_ref.py" --write "$T/$name" "${spec#restride:}" > /dev/null 2>&1 ;;
    add:*) a=${spec#add:}; set_=${a%%:*}; net=${a#*:}; src="$T/$name/$net.json"
           if [ "$set_" = random ]; then s_=${net#r}; s_=$((10#$s_)); xa=(--set random --seed "$s_" --count 1); else xa=(); fi
           python3 -I "$R/ncpgen/add_sweep.py" write "$T/$name" "$net" "${xa[@]}" > /dev/null 2>&1 ;;
    *) src="$T/$name.json"
       python3 -I "$R/oracle/npuc-variant.py" "$src" $spec > /dev/null 2>&1 ;;
  esac \
    && python3 -I "$R/ncpgen/ncpgen.py" gen "$src" "$T/$name.ncp" $opts --grelu npuc > /dev/null 2>&1 \
    && [ "$(sha256sum < "$T/$name.ncp" | cut -d' ' -f1)" = "$sha" ] && echo "ok $name" || echo "FAIL $name"
  rm -rf "$T/$name" "$T/$name.ncp"
}
export -f one; export R T
# the zoo's models first: the largest take tens of seconds, the others run beside them
res=$({ grep '^zoo-' "$R/tests/golden.txt"; grep -v -e '^#' -e '^zoo-' "$R/tests/golden.txt"; } | tr '\n' '\0' \
  | xargs -0 -n 1 -P "$J" bash -c 'one "$1"' _)
n=$(echo "$res" | grep -c '^ok '); m=$(echo "$res" | grep -c '^FAIL ')
echo "$res" | grep '^FAIL ' || true
echo "golden: $n of $((n + m)) NCPs byte for byte = NPUC's"
[ "$m" = 0 ] || fail=1
tfl() {
  python3 -I "$R/models/zoo.py" write "$T/tfl-$1" "$1" 2>&1 | grep -q 'tflite: ok' && echo "ok $1" || echo "FAIL $1"
  rm -rf "$T/tfl-$1"
}
export -f tfl
res=$(python3 -I "$R/models/zoo.py" list | cut -d' ' -f1 | xargs -n 1 -P "$J" bash -c 'tfl "$1"' _)
n=$(echo "$res" | grep -c '^ok '); m=$(echo "$res" | grep -c '^FAIL ')
echo "$res" | grep '^FAIL ' | sed 's/^/tflite /' || true
echo "zoo TFLite: $n of $((n + m)) models lower as their JSON"
[ "$m" = 0 ] || fail=1
[ $fail = 0 ] && echo "tests: PASS" || echo "tests: FAIL"
exit $fail
